@app.cell
def _(MODEL_KEY, dependency_runtime, mo):
    assert dependency_runtime["status"] == "READY"
    WigglyDashboard = (
        __import__("importlib")
        .import_module("bifocalgemma.training.wiggly_dashboard")
        .WigglyDashboard
    )

